/* GFR 2017 — Chapter 6, Part A: PROCUREMENT OF GOODS (Rules 142–176)
   Verbatim text from the DoE compilation of GFR 2017 updated up to 31.01.2026.
   Fields: r=rule, t=title, text=verbatim, hi=Hinglish, subs[]=clause-level,
   prov[]=provisos, note[]=notes/explanations, ex[]=exceptions, fn[]=footnotes */
window.GFR_CH6_GOODS = [
{r:'142', t:'Scope of the Chapter',
 text:'This chapter contains the general rules applicable to all Ministries or Departments, regarding procurement of goods required for use in the public service. Detailed instructions relating to procurement of goods may be issued by the procuring departments broadly in conformity with the general rules contained in this Chapter.',
 hi:'Chapter 6 ka pehla rule — scope. Saari Central Government Ministries/Departments par lagu hota hai. Department apni khud ki detailed procedures bana sakti hai, lekin unhe in general rules ke "broadly in conformity" mein hona chahiye — yaani in rules ke khilaf nahi ja sakte.',
 fn:[]},

{r:'143', t:'Definition of Goods',
 text:"The term 'goods' used in this chapter includes all articles, material, commodity, livestock, furniture, fixtures, raw material, spares, instruments, machinery, equipment, industrial plant, vehicles, aircraft, ships, medicines, railway rolling stock, assemblies, subassemblies, accessories, a group of machineries comprising of an integrated production process or such other category of goods or intangible products like software, technology transfer, licenses, patents or other intellectual properties purchased or otherwise acquired for the use of Government but excludes books, publications, periodicals, etc. for a library. The term 'goods' also includes works and services which are incidental or consequential to the supply of such goods, such as, transportation, insurance, installation, commissioning, training and maintenance.",
 hi:'"Goods" ka matiya sirf cheezein nahi — software, technology transfer, licences, patents aur doosre intellectual properties bhi ismein aate hain. Supply ke saath hone wale incidental works/services (transport, insurance, installation, commissioning, training, maintenance) bhi "goods" ke andar hain.',
 ex:['Books, publications, periodicals etc. FOR A LIBRARY are expressly excluded from the definition of "goods".'],
 note:['Intangible products (software, technology transfer, licences, patents, IP) are included.','Incidental / consequential works and services (transportation, insurance, installation, commissioning, training, maintenance) are included.'],
 fn:[]},

{r:'144', t:'Fundamental principles of public buying (for all procurements including procurement of works)',
 text:'Every authority delegated with the financial powers of procuring goods in public interest shall have the responsibility and accountability to bring efficiency, economy, and transparency in matters relating to public procurement and for fair and equitable treatment of suppliers and promotion of competition in public procurement. The procedure to be followed in making public procurement must conform to the following yardsticks:',
 hi:'Public buying ke 10 yardsticks. Ye "should" ke roop mein hain — inhe follow karna hai, aur inme se kuch (jaise Annual Procurement Plan) "shall" hain. Procurement of works par bhi yehi lagu hote hain.',
 subs:[
  {n:'144(i)(a)', text:'The description of the subject matter of procurement to the extent practicable should be objective, functional, generic and measurable and specify technical, qualitative and performance characteristics.', hi:'Specification generic honi chahiye — brand ke naam par nahi.'},
  {n:'144(i)(b)', text:'The description … should not indicate a requirement for a particular trade mark, trade name or brand.', hi:'Trade mark / trade name / brand ka zikr mana hai.'},
  {n:'144(ii)', text:'The specifications in terms of quality, type etc., as also quantity of goods to be procured, should be clearly spelt out keeping in view the specific needs of the procuring organisations. The specifications so worked out should meet the basic needs of the organisation without including superfluous and non-essential features, which may result in unwarranted expenditure.', hi:'Sirf zaroorat ke hisaab se specification — extra features = extra kharcha.'},
  {n:'144(iii)', text:'Where applicable, the technical specifications shall, to the extent practicable, be based on the national technical regulations or recognized national standards or building codes, wherever such standards exist, and in their absence, be based on the relevant international standards. In case of Government of India funded projects abroad, the technical specifications may be framed based on requirements and standards of the host beneficiary Government, where such standards exist.', hi:'Pehle national standards, warna international standards.'},
  {n:'144(iv)', text:'Care should also be taken to avoid purchasing quantities in excess of requirement to avoid inventory carrying costs.', hi:'Zaroorat se zyada quantity mat lo — inventory carrying cost badhti hai.'},
  {n:'144(v)', text:'Offers should be invited following a fair, transparent and reasonable procedure.', hi:'Offers fair, transparent aur reasonable procedure se maango.'},
  {n:'144(vi)', text:'The procuring authority should be satisfied that the selected offer adequately meets the requirement in all respects.', hi:'Selected offer requirement poori tarah meet karti hai — ye satisfy karna zaroori.'},
  {n:'144(vii)', text:'The procuring authority should satisfy itself that the price of the selected offer is reasonable and consistent with the quality required.', hi:'Price reasonable aur quality ke hisaab se hona chahiye.'},
  {n:'144(viii)', text:'A complete schedule of procurement cycle from date of issuing the tender to date of issuing the contract should be published when the tender is issued.', hi:'Tender ke saath poora procurement cycle schedule publish karo.'},
  {n:'144(ix)', text:'All Ministries/Departments shall prepare Annual Procurement Plan before the commencement of the year and the same should also be placed on their website.', hi:'Annual Procurement Plan saal shuru hone se pehle + website par.'}
 ],
 prov:['Rule 144(iii) Proviso: "Provided that a procuring entity may, for reasons to be recorded in writing, adopt any other technical specification." — kisi doosri technical specification apnani ho to wajah likh kar record karni hogi.'],
 ex:['Rule 144(x): DoE may, by order in writing, impose restrictions including prior registration and/or screening on procurement from bidders from (or having commercial arrangements with an entity from) a country or class of countries, on grounds of defence of India or matters directly or indirectly related thereto including national security. No procurement shall be made in violation of such restrictions.'],
 note:['Rule 144(iii) proviso is the only escape route in the yardsticks — and it requires reasons to be recorded in writing.'],
 fn:['Rule 144(x) inserted vide DoE OM No. F.7/10/2021-PPD dated 23.02.2023 (restrictions on bidders from countries sharing a land border).']},

{r:'145', t:'Authorities competent to purchase goods',
 text:'An authority which is competent to incur expenditure may sanction the purchase of goods required for use in public service in accordance with provisions in the Delegation of Financial Powers Rules, following the general procedure contained in the following rules.',
 hi:'Purchase sanction karne ki power = expenditure incur karne ki power, jo Delegation of Financial Powers Rules mein di gayi hai. Iske baad neeche diye gaye general procedure follow karne hain.',
 fn:[]},

{r:'146', t:'Procurement of goods required on mobilisation',
 text:'Procurement of goods required on mobilisation and/or during the continuance of Military operations shall be regulated by special rules and orders issued by the Government on this behalf from time to time.',
 hi:'Military operations ke dauraan / mobilisation ke liye goods — in par alag special rules aur Government orders lagu hote hain, Chapter 6 ke general rules nahi.',
 ex:['Mobilisation and military operations — governed by special rules and orders issued by Government from time to time.'],
 fn:[]},

{r:'147', t:'Powers for procurement of goods',
 text:'The Ministries or Departments have been delegated full powers to make their own arrangements for procurement of goods and services, that are not available on GeM. Common use Goods and Services available on GeM are required to be procured mandatorily through GeM as per Rule 149.',
 hi:'Jo goods/services GeM par available hain — unhe mandatorily GeM se lena hai. Jo available nahi hain, unke liye Ministry ko full powers hain apni arrangement karne ki.',
 fn:['Amended vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'148', t:'Rate Contract — DELETED',
 text:'Rule 148 (Rate Contract) stands deleted.',
 hi:'Rule 148 (Rate Contract) delete ho chuka hai — DGS&D rate contracts ki baat ab is rule mein nahi hai.',
 ex:['The entire Rule 148 has been deleted.'],
 fn:['Deleted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'149', t:'Government e-Market place (GeM)',
 text:'Government of India has established the Government e-Marketplace (GeM) for common use Goods and Services. GeM SPV will ensure adequate publicity including periodic advertisement of the items to be procured through GeM for the prospective suppliers. The Procurement of Goods and Services by Ministries or Departments will be mandatory for Goods or Services available on GeM. The credentials of suppliers on GeM shall be certified by GeM SPV. The procuring authorities will certify the reasonability of rates. The GeM portal shall be utilized by the Government buyers for direct online purchases as under:',
 hi:'GeM ka pura ladder — value ke hisaab se teen tiers. Ye woh rule hai jo 10.07.2024 ke OM se sabse zyada badla, isliye memory se nahi, latest source se padhna zaroori.',
 subs:[
  {n:'149(i)', text:'Up to ₹50,000/- through any of the available suppliers on the GeM, meeting the requisite quality, specification and delivery period.', hi:'₹50,000 tak — GeM par kisi bhi available supplier se seedha purchase.'},
  {n:'149(ii)', text:'Above ₹50,000/- and up to ₹10,00,000/- through the GeM Seller having lowest price amongst the available sellers, of at least three different manufacturers, on GeM, meeting the requisite quality, specification and delivery period. The tools for online bidding and online reverse auction available on GeM can be used by the Buyer even for procurements less than ₹10,00,000.', hi:'₹50,000 se ₹10,00,000 tak — kam se kam 3 different manufacturers mein sabse kam price (L-1) wala GeM seller. ₹10 lakh se neeche bhi online bidding/reverse auction tool use kar sakte hain.'},
  {n:'149(iii)', text:'Above ₹10,00,000/- through the supplier having lowest price meeting the requisite quality, specification and delivery period after mandatorily obtaining bids, using online bidding or reverse auction tool provided on GeM.', hi:'₹10,00,000 se upar — online bidding ya reverse auction tool se bids lena MANDATORY hai, phir L-1 supplier select.'},
  {n:'149(iv)', text:'The invitation for the online e-bidding/reverse auction will be available to all the existing Sellers or other Sellers registered on the portal and who have offered their goods/services under the particular product/service category, as per terms and conditions of GeM.', hi:'Auction ka invitation sabhi registered sellers tak pahunchna chahiye — sirf chune hue sellers tak nahi.'},
  {n:'149(v)', text:'The above-mentioned monetary ceiling is applicable only for purchases made through GeM. For purchases, if any, outside GeM, relevant GFR Rules shall apply.', hi:'Ye monetary ceilings sirf GeM purchases par lagu hain. GeM ke bahar ki purchase par baaki GFR rules lagu honge.'},
  {n:'149(vi)', text:'The Ministries/Departments shall work out their procurement requirements of Goods and Services on either "OPEX" model or "CAPEX" model as per their requirement/suitability at the time of preparation of Budget Estimates (BE) and shall project their Annual Procurement Plan of goods and services on GeM portal within 30 days of Budget approval.', hi:'OPEX ya CAPEX model chuno, aur Budget approval ke 30 din ke andar Annual Procurement Plan GeM par project karo.'},
  {n:'149(vii)', text:'The Government Buyers may ascertain the reasonableness of prices before placement of order using the Business Analytics (BA) tools available on GeM including the Last Purchase Price on GeM, Department\u2019s own Last Purchase Price etc.', hi:'Order se pehle GeM ke Business Analytics tools se price reasonableness check kar sakte hain.'},
  {n:'149(viii)', text:'A demand for goods shall not be divided into small quantities to make piecemeal purchases to avoid procurement through L-1 Buying / bidding / reverse auction on GeM or the necessity of obtaining the sanction of higher authorities required with reference to the estimated value of the total demand.', hi:'Demand ko tod kar piecemeal purchase karna mana hai — na bidding se bachna, na higher sanction se.'}
 ],
 note:['Note to Rule 149(i): "In case of automobiles, procurement under this sub-rule is permitted without any ceiling limit."'],
 ex:['Automobiles — no ceiling limit under Rule 149(i) as per the Note.','Rule 149(v): ceilings apply only to purchases made through GeM; outside GeM, relevant GFR Rules apply.'],
 fn:['Sub-rules (i), (ii), (iii) amended vide DoE OM No. F.1/3/2024-PPD dated 10.07.2024 (₹25,000/₹5,00,000/₹30,00,000 → ₹50,000/₹10,00,000/₹10,00,000).',
     'SOURCE CONFLICT FLAGGED: the official DoE compilation places the "automobiles — no ceiling" Note immediately after sub-rule (i). Some secondary compilations instead show a ₹30 lakh continuation for automobiles inside sub-rules (ii)/(iii). The official compilation position is reproduced here; verify with your department for automobile tenders.']},

{r:'150', t:'Registration of Suppliers',
 text:'For goods and services not available on GeM, Head of Ministry/Department may also register suppliers of goods and services which are specifically required by that Department or Office, periodically. Registration of the supplier should be done following a fair, transparent and reasonable procedure and after giving due publicity. Such registered suppliers should be boarded on GeM as and when the item or service gets listed on GeM. Credentials, manufacturing capability, quality control systems, past performance, after-sales service, financial background etc. of the supplier(s) should be carefully verified before registration. The supplier(s) will be registered for a fixed period (between 1 to 3 years) depending on the nature of the goods. At the end of this period, the registered supplier(s) willing to continue with registration are to apply afresh for renewal of registration. New supplier(s) may also be considered for registration at anytime, provided they fulfill all the required conditions. Performance and conduct of every registered supplier is to be watched by the concerned Ministry or Department. The registered supplier(s) are liable to be removed from the list of approved suppliers if they fail to abide by the terms and conditions of the registration or fail to supply the goods on time or supply substandard goods or make any false declaration to any Government agency or for any ground which, in the opinion of the Government, is not in public interest. The list of registered suppliers for the subject matter of procurement be exhibited on websites of the Procuring Entity/ their e-Procurement portals.',
 hi:'GeM par available na hone wale items ke liye supplier register karne ka prakriya. Registration 1–3 saal ki hoti hai, credentials verify karke, fair-transparent procedure se, due publicity ke saath. List website par rakhni hai.',
 subs:[
  {n:'150(i)', text:'For goods and services not available on GeM, Head of Ministry/Department may register suppliers … periodically, following a fair, transparent and reasonable procedure and after giving due publicity. Such registered suppliers should be boarded on GeM as and when the item or service gets listed on GeM.', hi:'Sirf GeM par available na hone wali cheezon ke liye. Item GeM par aate hi supplier ko GeM par board karna hai.'},
  {n:'150(ii)', text:'Credentials, manufacturing capability, quality control systems, past performance, after-sales service, financial background etc. of the supplier(s) should be carefully verified before registration.', hi:'Registration se pehle credentials verify karna zaroori.'},
  {n:'150(iii)', text:'The supplier(s) will be registered for a fixed period (between 1 to 3 years) depending on the nature of the goods. At the end of this period, the registered supplier(s) willing to continue with registration are to apply afresh for renewal of registration. New supplier(s) may also be considered for registration at anytime, provided they fulfill all the required conditions.', hi:'Registration 1–3 saal; renewal ke liye naya application; naye suppliers kabhi bhi consider ho sakte hain.'},
  {n:'150(iv)', text:'Performance and conduct of every registered supplier is to be watched … The registered supplier(s) are liable to be removed … if they fail to abide by the terms and conditions of the registration or fail to supply the goods on time or supply substandard goods or make any false declaration to any Government agency or for any ground which, in the opinion of the Government, is not in public interest.', hi:'Removal ke 4+ grounds: terms todna, time par supply na karna, substandard goods, false declaration, ya public interest.'},
  {n:'150(v)', text:'The list of registered suppliers for the subject matter of procurement be exhibited on websites of the Procuring Entity/ their e-Procurement portals.', hi:'Registered suppliers ki list website/e-procurement portal par.'}
 ],
 fn:['Amended vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'151', t:'Debarment from bidding',
 text:'A bidder shall be debarred if he has been convicted of an offence—(a) under the Prevention of Corruption Act, 1988; or (b) the Indian Penal Code or any other law for the time being in force, for causing any loss of life or property or causing a threat to public health as part of execution of a public procurement contract. A bidder debarred under sub-section (i) or any successor of the bidder shall not be eligible to participate in a procurement process of any procuring entity for a period not exceeding three years commencing from the date of debarment. Department of Expenditure will maintain such list which will also be displayed on the Central Public Procurement Portal. A procuring entity may debar a bidder or any of its successors, from participating in any procurement process undertaken by it, for a period not exceeding two years, if it determines that the bidder has breached the code of integrity. The Ministry/Department will maintain such list which will also be displayed on their website. The bidder shall not be debarred unless such bidder has been given a reasonable opportunity to represent against such debarment.',
 hi:'Debarment ke do alag raste: (1) conviction par — kisi bhi procuring entity se 3 saal tak (DoE list, CPPP par); (2) code of integrity todne par — us entity se 2 saal tak (Ministry list, website par). Dono mein "reasonable opportunity to represent" dena zaroori hai.',
 subs:[
  {n:'151(i)(a)', text:'A bidder shall be debarred if he has been convicted of an offence under the Prevention of Corruption Act, 1988.', hi:'PC Act 1988 ki conviction — automatic debarment ground.'},
  {n:'151(i)(b)', text:'… or the Indian Penal Code or any other law for the time being in force, for causing any loss of life or property or causing a threat to public health as part of execution of a public procurement contract.', hi:'IPC/any law — jaan-maal ki haani ya public health ko khatra, procurement contract ke execution ke dauran.'},
  {n:'151(ii)', text:'A bidder debarred under sub-section (i) or any successor of the bidder shall not be eligible to participate in a procurement process of any procuring entity for a period not exceeding three years commencing from the date of debarment. Department of Expenditure will maintain such list which will also be displayed on the Central Public Procurement Portal.', hi:'3 saal tak — kisi bhi procuring entity se. List DoE rakhta hai, CPPP par display.'},
  {n:'151(iii)', text:'A procuring entity may debar a bidder or any of its successors, from participating in any procurement process undertaken by it, for a period not exceeding two years, if it determines that the bidder has breached the code of integrity. The Ministry/Department will maintain such list which will also be displayed on their website.', hi:'Code of integrity ka breach — 2 saal tak us entity se. List Ministry rakhti hai, website par.'},
  {n:'151(iv)', text:'The bidder shall not be debarred unless such bidder has been given a reasonable opportunity to represent against such debarment.', hi:'Bina reasonable opportunity ke debarment nahi ho sakta.'}
 ],
 fn:['Amended vide DoE OM No. F.1/20/2018-PPD dated 02.11.2021.']},

{r:'152', t:'Enlistment of Indian Agents',
 text:'Ministries/Departments if they so require, may enlist Indian agents, who desire to quote directly on behalf of their foreign principals.',
 hi:'Ministry chahe to un Indian agents ko enlist kar sakti hai jo apne foreign principals ki taraf se seedha quote karna chahte hain. Ye "may" hai — discretionary.',
 fn:['Amended vide DoE OM No. F.26/2/2016-PPD dated 25.07.2017.']},

{r:'153', t:'Reserved Items and other Purchase/Price Preference Policy',
 text:'The Central Government, through administrative instructions, has reserved all items of hand spun and handwoven textiles (khadi goods) for exclusive purchase from Khadi Village Industries Commission (KVIC). Of all items of textiles required by Central Government departments, it shall be mandatory to make procurement of at least 20% from amongst items of handloom origin, for exclusive purchase from KVIC and/or Handloom Clusters such as Co-Operative Societies, Self Help Group (SHG) Federations, Joint Liability Group (JLG), Producer Companies (PC), Corporations etc. including Weavers having Pehchan Cards. Ministry of Micro, Small and Medium Enterprises (MSME) have notified procurement policy under section 11 of the Micro, Small and Medium Enterprises Development Act, 2006. The Central Government may, by notification, provide for mandatory procurement of any goods or services from any category of bidders, or provide for preference to bidders on the grounds of promotion of locally manufactured goods or locally provided services.',
 hi:'Reserved items: khadi goods sirf KVIC se. Textiles mein kam se kam 20% handloom origin se (KVIC / Handloom Clusters / SHG Federations / JLG / Producer Companies / Pehchan Card weavers). MSME procurement policy Section 11 MSMED Act 2006 ke tehat. Local manufacturing preference notification se aa sakti hai.',
 subs:[
  {n:'153(i)', text:'All items of hand spun and handwoven textiles (khadi goods) are reserved for exclusive purchase from KVIC. Of all items of textiles required, it shall be mandatory to procure at least 20% from items of handloom origin — KVIC and/or Handloom Clusters such as Co-Operative Societies, SHG Federations, JLG, Producer Companies, Corporations etc. including Weavers having Pehchan Cards.', hi:'Khadi = sirf KVIC. Textiles ka 20% handloom origin se.'},
  {n:'153(ii)', text:'Ministry of Micro, Small and Medium Enterprises (MSME) have notified procurement policy under section 11 of the Micro, Small and Medium Enterprises Development Act, 2006.', hi:'MSME procurement policy alag se notified hai.'},
  {n:'153(iii)', text:'The Central Government may, by notification, provide for mandatory procurement of any goods or services from any category of bidders, or provide for preference to bidders on the grounds of promotion of locally manufactured goods or locally provided services.', hi:'Notification se kisi category ko mandatory ya locally-manufactured ko preference diya ja sakta hai.'}
 ],
 fn:['Amended vide DoE OM No. F.10/2/2019-PPD(Pt.) dated 17.02.2020.']},

{r:'154', t:'Purchase of goods without quotation',
 text:'Purchase of goods upto the value of ₹50,000 (Rupees fifty thousand only) on each occasion may be made without inviting quotations or bids on the basis of a certificate to be recorded by the competent authority in the following format. "I … am personally satisfied that these goods purchased are of the requisite quality and specification and have been purchased from a reliable supplier at a reasonable price."',
 hi:'₹50,000 tak (har occasion par) bina quotation/bids ke purchase — bas competent authority ka personal satisfaction certificate record karna hai. Ye certificate likhna optional nahi, rule ka hissa hai.',
 note:['Prescribed certificate: "I … am personally satisfied that these goods purchased are of the requisite quality and specification and have been purchased from a reliable supplier at a reasonable price."'],
 ex:['Scientific Ministries/Departments/Organisations (DST, DBT, DSIR, DAE, Space, MoES, DRDO, ICAR + affiliated institutions & universities, DHR incl. ICMR, and educational/research institutes conducting post-graduate/doctoral courses or research under any Ministry/Department): limit raised to ₹2,00,000 — vide DoE OM No. F.20/42/2021-PPD dated 05.06.2025. Applicable only for scientific equipment and consumables for research purposes, and only when not available on GeM.'],
 fn:['Amended vide DoE OM No. F.1/3/2024-PPD dated 10.07.2024 (₹25,000 → ₹50,000).',
     'Special higher limit for Scientific Ministries inserted vide DoE OM No. F.20/42/2021-PPD dated 20.05.2024 and further raised vide DoE OM No. F.20/42/2021-PPD dated 05.06.2025.']},

{r:'155', t:'Purchase of goods by Purchase Committee',
 text:'In case a certain item is not available on the GeM portal, purchase of goods costing above ₹50,000 (Rupees Fifty thousand only) and upto ₹5,00,000/- (Rupees Five lakh only) on each occasion may be made on the recommendations of a duly constituted Local Purchase Committee consisting of three members of an appropriate level as decided by the Head of the Department. The committee will survey the market to ascertain the reasonableness of rate, quality and specifications and identify the appropriate supplier. Before recommending placement of the purchase order, the members of the committee will jointly record a certificate as under: "Certified that we, members of the purchase committee are jointly and individually satisfied that the goods recommended for purchase are of the requisite specification and quality, priced at the prevailing market rate and the supplier recommended is reliable and competent to supply the goods in question, and it is not debarred by Department of Expenditure or Ministry/Department concerned."',
 hi:'₹50,000 se zyada aur ₹5,00,000 tak — sirf jab item GeM par available na ho. Teen members ka Local Purchase Committee banega, market survey karega, aur joint certificate dega. Certificate mein "not debarred" ka confirmation bhi hai.',
 subs:[
  {n:'155 — LPC composition', text:'A duly constituted Local Purchase Committee consisting of three members of an appropriate level as decided by the Head of the Department.', hi:'3 members, level Head of Department decide karega.'},
  {n:'155 — Market survey', text:'The committee will survey the market to ascertain the reasonableness of rate, quality and specifications and identify the appropriate supplier.', hi:'Market survey karke rate/quality/specification ki reasonableness aur supplier identify karo.'},
  {n:'155 — Joint certificate', text:'Certified that we, members of the purchase committee are jointly and individually satisfied that the goods recommended for purchase are of the requisite specification and quality, priced at the prevailing market rate and the supplier recommended is reliable and competent to supply the goods in question, and it is not debarred by Department of Expenditure or Ministry/Department concerned.', hi:'Joint + individual satisfaction, prevailing market rate, reliable & competent supplier, aur supplier debarred na ho.'}
 ],
 ex:['Scientific Ministries: ₹2,00,000 to ₹25,00,000 (DoE OM No. F.20/42/2021-PPD dated 05.06.2025).','Applies only where the item is NOT available on the GeM portal (condition inserted vide OM dated 02.04.2019).'],
 fn:['"In case a certain item is not available on the GeM portal" inserted vide DoE OM No. F.1.26/2018-PPD dated 02.04.2019.',
     'Special higher limits for Scientific Ministries vide DoE OM No. F.20/42/2021-PPD dated 20.05.2024 and 05.06.2025.']},

{r:'156', t:'Purchase of goods by obtaining quotations — DELETED',
 text:'Rule 156 stands deleted.',
 hi:'Rule 156 (purana "obtaining quotations" rule) delete ho chuka hai. Ab ₹50,000–₹5,00,000 ka purchase Rule 155 (Purchase Committee) se hota hai.',
 ex:['The entire Rule 156 has been deleted.'],
 fn:['Deleted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'157', t:'Prohibition of splitting of demand',
 text:'A demand for goods should not be divided into small quantities to make piecemeal purchases to avoid the necessity of obtaining the sanction of higher authority required with reference to the estimated value of the total demand.',
 hi:'Anti-splitting rule. Total demand ki estimated value dekh kar higher authority ki sanction leni padegi — demand ko chhote hisson mein baant kar bachna allowed nahi.',
 fn:[]},

{r:'158', t:'Purchase of goods by obtaining bids',
 text:'Except in cases covered under Rule 154 and 155, Ministries or Departments shall procure goods under the powers referred to in Rule 140 above by following the standard method of obtaining bids in: (i) Advertised Tender Enquiry (ii) Limited Tender Enquiry (iii) Two-Stage Bidding (iv) Single Tender Enquiry (v) Electronic Reverse Auctions.',
 hi:'Rule 154/155 ke cases ko chhod kar, baaki sab procurement in paanch standard methods se hogi.',
 subs:[
  {n:'158(i)', text:'Advertised Tender Enquiry', hi:'Rule 161'},
  {n:'158(ii)', text:'Limited Tender Enquiry', hi:'Rule 162'},
  {n:'158(iii)', text:'Two-Stage Bidding', hi:'Rule 164'},
  {n:'158(iv)', text:'Single Tender Enquiry', hi:'Rule 166'},
  {n:'158(v)', text:'Electronic Reverse Auctions', hi:'Rule 167'}
 ],
 ex:['Procurements covered by Rule 154 (without quotation) and Rule 155 (purchase committee) are outside Rule 158.'],
 fn:[]},

{r:'159', t:'E-Publishing',
 text:'It is mandatory for all Ministries/Departments of the Central Government, their attached and Subordinate Offices and Autonomous/Statutory Bodies to publish their tender enquiries, corrigenda thereon and details of bid awards on the Central Public Procurement Portal (CPPP). Individual cases where confidentiality is required, for reasons of national security, would be exempted from the mandatory e-publishing requirement. The decision to exempt any case on the said grounds should be approved by the Secretary of the Ministry/Department with the concurrence of the concerned Financial Advisor. In the case of Autonomous Bodies and Statutory Bodies approval of the Head of the Body with the concurrence of the Head of the Finance should be obtained in each such case. Statistical information on the number of cases in which exemption was granted and the value of the concerned contract should be intimated on a Quarterly basis to the Ministry of Finance, Department of Expenditure. The above instructions apply to all Tender Enquiries, Requests for Proposals, Requests for Expressions of Interest, Notice for pre-Qualification/Registration or any other notice inviting bids or proposals in any form whether they are advertised, issued to limited number of parties or to a single party. These instructions would not apply to procurements made in terms of provisions of Rules 154 (Purchase of goods without quotations) or 155 (Purchase of goods by purchase committee) of General Financial Rules.',
 hi:'Tender enquiry, corrigenda aur bid award details CPPP par publish karna MANDATORY hai — har ministry, attached/subordinate office, autonomous/statutory body ke liye. Limited ya single party ko bhi jaane wale notices par bhi lagu. Rules 154/155 ki purchases par lagu nahi.',
 subs:[
  {n:'159(i)', text:'Mandatory for all Ministries/Departments of the Central Government, their attached and Subordinate Offices and Autonomous/Statutory Bodies to publish their tender enquiries, corrigenda thereon and details of bid awards on the Central Public Procurement Portal (CPPP).', hi:'Tender + corrigenda + award details — sab CPPP par.'},
  {n:'159(ii)', text:'Individual cases where confidentiality is required, for reasons of national security, would be exempted … approved by the Secretary of the Ministry/Department with the concurrence of the concerned Financial Advisor. In the case of Autonomous Bodies and Statutory Bodies, approval of the Head of the Body with the concurrence of the Head of the Finance should be obtained in each such case. Statistical information on the number of cases in which exemption was granted and the value of the concerned contract should be intimated on a Quarterly basis to DoE.', hi:'National security exemption — Secretary + FA concurrence; Autonomous/Statutory bodies — Head + Head of Finance; har quarter DoE ko statistics bhejni hai.'},
  {n:'159(iii)', text:'The above instructions apply to all Tender Enquiries, Requests for Proposals, Requests for Expressions of Interest, Notice for pre-Qualification/Registration or any other notice inviting bids or proposals in any form whether they are advertised, issued to limited number of parties or to a single party.', hi:'RFP, REOI, pre-qualification notices — sab par lagu, chahe advertised ho ya single party ko.'},
  {n:'159(iv)', text:'[Deleted]', hi:'Sub-rule (iv) delete ho chuka hai.'},
  {n:'159(v)', text:'These instructions would not apply to procurements made in terms of provisions of Rules 154 (Purchase of goods without quotations) or 155 (Purchase of goods by purchase committee) of General Financial Rules.', hi:'Rule 154/155 ki purchases CPPP publishing se bahar hain.'}
 ],
 ex:['National-security confidentiality cases — exempt with Secretary + Financial Adviser concurrence (Head of Body + Head of Finance for autonomous/statutory bodies), plus quarterly statistical intimation to DoE.','Rules 154 and 155 procurements are exempt from e-publishing.'],
 fn:['Sub-rule (iv) deleted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'160', t:'E-Procurement',
 text:'It is mandatory for Ministries/Departments to receive all bids through e-procurement portals in respect of all procurements. Ministries/Departments which do not have a large volume of procurement or carry out procurements required only for day-to-day running of offices and also have not initiated e-procurement through any other solution provided so far, may use e-procurement solution developed by NIC. Other Ministries/Departments may either use e-procurement solution developed by NIC or engage any other service provider following due process. In individual case where national security and strategic considerations demands confidentiality, Ministries/Departments may exempt such cases from e-procurement after seeking approval of concerned Secretary and with concurrence of Financial Advisers. In case of tenders floated by Indian Missions Abroad, Competent Authority to decide the tender, may exempt such case from e-procurement.',
 hi:'Saare bids e-procurement portal par lena MANDATORY. Chhote volume wali departments NIC ka solution use kar sakti hain; baaki NIC ya kisi doosre service provider ko due process se engage kar sakti hain.',
 subs:[
  {n:'160(i)', text:'It is mandatory for Ministries/Departments to receive all bids through e-procurement portals in respect of all procurements.', hi:'Sab bids portal par.'},
  {n:'160(ii)', text:'Ministries/Departments which do not have a large volume of procurement or carry out procurements required only for day-to-day running of offices and also have not initiated e-procurement through any other solution provided so far, may use e-procurement solution developed by NIC. Other Ministries/Departments may either use e-procurement solution developed by NIC or engage any other service provider following due process.', hi:'NIC solution ya due process se koi doosra provider.'},
  {n:'160(iii)', text:'[Deleted]', hi:'Sub-rule (iii) delete ho chuka hai.'},
  {n:'160(iv)', text:'In individual case where national security and strategic considerations demands confidentiality, Ministries/Departments may exempt such cases from e-procurement after seeking approval of concerned Secretary and with concurrence of Financial Advisers.', hi:'National security / strategic — Secretary approval + FA concurrence.'},
  {n:'160(v)', text:'In case of tenders floated by Indian Missions Abroad, Competent Authority to decide the tender, may exempt such case from e-procurement.', hi:'Indian Missions Abroad ke tenders — competent authority exempt kar sakta hai.'}
 ],
 ex:['National security and strategic considerations — Secretary approval with Financial Adviser concurrence.','Tenders floated by Indian Missions Abroad — competent authority may exempt.'],
 fn:['Sub-rule (iii) deleted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'161', t:'Advertised Tender Enquiry',
 text:'Subject to exceptions incorporated under Rule 154, 155, 162 and 166, invitation to tenders by advertisement should be used for procurement of goods of estimated value of ₹50 lakhs (Rupees Fifty Lakh) and above. Advertisement in such cases should be given on GeM as well as on GeM-Central Public Procurement Portal (CPPP). An organisation having its own website should also publish all its advertised tender enquiries on the website. The organisation should also post the complete bidding document in its website and on CPPP to enable prospective bidders to make use of the document by downloading from the web site. The advertisements for invitation of tenders should give the complete web address from where the bidding documents can be downloaded. In order to promote wider participation and ease of bidding, no cost of tender document may be charged for the tender documents downloaded by the bidders. Ordinarily, the minimum time to be allowed for submission of bids should be three weeks from the date of publication of the tender notice or availability of the bidding document for sale, whichever is later. Where the Department also contemplates obtaining bids from abroad, the minimum period should be kept as four weeks for both domestic and foreign bidders.',
 hi:'₹50 lakh aur upar ke goods ke liye advertised tender. Advertisement GeM + GeM-CPP par, apni website par bhi. Tender document free download. Minimum 3 hafte (foreign bidders bhi chahiye to 4 hafte).',
 subs:[
  {n:'161(i)', text:'Invitation to tenders by advertisement should be used for procurement of goods of estimated value of ₹50 lakhs and above. Advertisement should be given on GeM as well as on GeM-Central Public Procurement Portal (CPPP). An organisation having its own website should also publish all its advertised tender enquiries on the website.', hi:'₹50 lakh+ → advertised tender; GeM + GeM-CPP + own website.'},
  {n:'161(ii)', text:'The organisation should also post the complete bidding document in its website and on CPPP to enable prospective bidders to make use of the document by downloading from the web site.', hi:'Poora bidding document website aur CPPP par.'},
  {n:'161(iii)', text:'The advertisements for invitation of tenders should give the complete web address from where the bidding documents can be downloaded.', hi:'Advertisement mein download ka pura web address ho.'},
  {n:'161(iv)(a)', text:'Global Tender Enquiry (GTE): where the Ministry or Department feels that the goods of the required quality, specifications etc., may not be available in the country and it is necessary to also look for suitable competitive offers from abroad, the Ministry or Department may send copies of the tender notice to the Indian Embassies abroad as well as to the Foreign Embassies in India. The selection of embassies will depend on the possibility of availability of the required goods in such countries. In such cases e-procurement as per Rule 160 may not be insisted.', hi:'GTE — goods desh mein na milne par; Indian Embassies abroad aur Foreign Embassies in India ko tender notice; e-procurement insist nahi ki jaati.'},
  {n:'161(iv)(b)', text:'No Global Tender Enquiry (GTE), however shall be invited for tenders up to ₹200 crore or such limit as may be prescribed by the Department of Expenditure from time to time. Provided that for tenders below such limit, in exceptional cases, where the Ministry or Department feels that there are special reasons for GTE, it may record its detailed justification and seek prior approval for relaxation to the above rule from the Competent Authority specified by the Department of Expenditure.', hi:'₹200 crore tak GTE nahi — proviso ke tehat exceptional case mein detailed justification + prior approval.'},
  {n:'161(v)', text:'In order to promote wider participation and ease of bidding, no cost of tender document may be charged for the tender documents downloaded by the bidders.', hi:'Downloaded tender document par koi charge nahi.'},
  {n:'161(vi)', text:'Ordinarily, the minimum time to be allowed for submission of bids should be three weeks from the date of publication of the tender notice or availability of the bidding document for sale, whichever is later. Where the Department also contemplates obtaining bids from abroad, the minimum period should be kept as four weeks for both domestic and foreign bidders.', hi:'3 hafte minimum; foreign bids bhi lene hain to 4 hafte.'}
 ],
 ex:['Exceptions under Rules 154, 155, 162 and 166.','GTE up to ₹200 crore prohibited; proviso allows prior approval with detailed justification.','Scientific Ministries: advertised tender for estimated value above ₹1 crore (DoE OM dated 05.06.2025).'],
 prov:['Rule 161(iv)(b) Proviso: in exceptional cases below the ₹200 crore limit, detailed justification may be recorded and prior approval for relaxation sought from the Competent Authority specified by DoE.'],
 fn:['Amended vide DoE OM No. F.1/3/2024-PPD dated 10.07.2024 (₹25 lakh → ₹50 lakh).',
     'Rule 161(iv) amended vide DoE OM No. F.12/17/2019-PPD dated 15.05.2020 (GTE ₹200 crore limit).']},

{r:'162', t:'Limited Tender Enquiry',
 text:'This method may be adopted when estimated value of the goods to be procured is up to ₹50 lakhs. Copies of the bidding document should be sent directly by speed post/registered post/courier/email to firms which are borne on the list of registered suppliers for the goods in question as referred under Rule 150 above. The number of supplier firms in Limited Tender Enquiry should be more than three. Efforts should be made to identify a higher number of approved suppliers to obtain more responsive bids on competitive basis. Further, an organisation should publish its limited tender enquiries on GeM as well as on GeM-Central Public Procurement Portal (CPPP). An organisation having its own website should also publish all its advertised tender enquiries on the website. The unsolicited bids should not be accepted. However, Ministries/Departments should evolve a system by which interested firms can register and bid in next round of tendering. Purchase through Limited Tender Enquiry may be adopted even where the estimated value of the procurement is more than ₹50 lakhs, in the following circumstances: (a) The competent authority in the Ministry or Department certifies that the demand is urgent and any additional expenditure involved by not procuring through advertised tender enquiry is justified in view of the urgency. The Ministry or Department should also put on record the nature of the urgency and reasons why the procurement could not be anticipated. (b) There are sufficient reasons, to be recorded in writing by the competent authority, indicating that it will not be in public interest to procure the goods through advertised tender enquiry. (c) The sources of supply are definitely known and possibility of fresh source(s) beyond those being tapped is remote. Sufficient time should be allowed for submission of bids in Limited Tender Enquiry cases.',
 hi:'₹50 lakh tak limited tender enquiry — registered suppliers (Rule 150) ko directly bhejo, teen se zyada firms. LTE enquiries bhi GeM + GeM-CPP par publish karni hain. Unsolicited bids accept nahi.',
 subs:[
  {n:'162(i)', text:'When estimated value of the goods to be procured is up to ₹50 lakhs. Copies of the bidding document should be sent directly by speed post/registered post/courier/email to firms borne on the list of registered suppliers (Rule 150). The number of supplier firms should be more than three. Efforts should be made to identify a higher number of approved suppliers to obtain more responsive bids on competitive basis. An organisation should publish its limited tender enquiries on GeM as well as on GeM-CPPP, and on its own website.', hi:'₹50 lakh tak LTE; >3 firms; GeM + GeM-CPP + own website par publish.'},
  {n:'162(ii)', text:'The unsolicited bids should not be accepted. However, Ministries/Departments should evolve a system by which interested firms can register and bid in next round of tendering.', hi:'Unsolicited bids nahi — par next round ke liye register karne ka system hona chahiye.'},
  {n:'162(iii)(a)', text:'LTE may be adopted even above ₹50 lakhs where the competent authority certifies that the demand is urgent and any additional expenditure involved by not procuring through advertised tender enquiry is justified in view of the urgency. The Ministry or Department should also put on record the nature of the urgency and reasons why the procurement could not be anticipated.', hi:'Urgency — competent authority certify kare, aur urgency ki nature + kyon anticipate nahi ho saka, record ho.'},
  {n:'162(iii)(b)', text:'There are sufficient reasons, to be recorded in writing by the competent authority, indicating that it will not be in public interest to procure the goods through advertised tender enquiry.', hi:'Public interest na hone ke likhit reasons.'},
  {n:'162(iii)(c)', text:'The sources of supply are definitely known and possibility of fresh source(s) beyond those being tapped is remote.', hi:'Supply sources definitely known hon aur naye sources ki sambhavna kam.'},
  {n:'162(iv)', text:'Sufficient time should be allowed for submission of bids in Limited Tender Enquiry cases.', hi:'LTE mein bhi bid submission ke liye kaafi time do.'}
 ],
 ex:['LTE above ₹50 lakh only in the three circumstances in Rule 162(iii)(a), (b) and (c), each requiring the competent authority to certify/record reasons.','Unsolicited bids are not to be accepted.','Scientific Ministries: LTE up to ₹1 crore (DoE OM dated 05.06.2025).'],
 fn:['Amended vide DoE OM No. F.1/3/2024-PPD dated 10.07.2024 (₹25 lakh → ₹50 lakh).',
     'Publication on GeM + GeM-CPP inserted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'163', t:'Two bid system (simultaneous receipt of separate technical and financial bids)',
 text:'For purchasing high value plant, machinery etc. of a complex and technical nature, bids may be obtained in two parts as under: (i) Technical bid consisting of all technical details along with commercial terms and conditions; and (ii) Financial bid indicating itemwise price for the items mentioned in the technical bid. The technical bid and the financial bid should be sealed by the bidder in separate covers duly super-scribed and both these sealed covers are to be put in a bigger cover which should also be sealed and duly super-scribed. The technical bids are to be opened by the purchasing Ministry or Department at the first instance and evaluated by a competent committee or authority. At the second stage financial bids of only these technically acceptable offers should be opened after intimating them the date and time of opening the financial bid for further evaluation and ranking before awarding the contract.',
 hi:'High value, complex plant/machinery ke liye two-bid. Technical aur financial alag sealed covers, dono ek bade cover mein. Technical pehle khulta hai; financial sirf technically acceptable offers ka.',
 subs:[
  {n:'163(i)', text:'Technical bid consisting of all technical details along with commercial terms and conditions.', hi:'Technical bid = technical details + commercial terms.'},
  {n:'163(ii)', text:'Financial bid indicating itemwise price for the items mentioned in the technical bid.', hi:'Financial bid = itemwise price.'},
  {n:'163 — procedure', text:'Technical and financial bids sealed in separate duly super-scribed covers; both put in a bigger sealed, super-scribed cover. Technical bids opened first and evaluated by a competent committee or authority. At the second stage, financial bids of only technically acceptable offers are opened after intimating them the date and time, for further evaluation and ranking before awarding the contract.', hi:'Alag covers → technical pehle → financial sirf technically acceptable offers ka.'}
 ],
 fn:[]},

{r:'164', t:'Two-Stage Bidding',
 text:'Ministry/Department may procure the subject matter of procurement by the method of two-stage bidding, if (a) it is not feasible to formulate detailed specifications or identify specific characteristics for the subject matter of procurement, without receiving inputs regarding its technical aspects from bidders; or (b) the character of the subject matter of procurement is subject to rapid technological advances or market fluctuations or both; or (c) Ministry/Department seeks to enter into a contract for the purpose of research, experiment, study or development, except where the contract includes the production of items in quantities sufficient to establish their commercial viability or to recover research and development costs; or (d) The bidder is expected to carry out a detailed survey or investigation and undertake a comprehensive assessment of risks, costs and obligations associated with the particular procurement. The procedure for two stage bidding shall include the following: (a) in the first stage … the Ministry/Department shall invite bids through advertised tender containing the technical aspects and contractual terms and conditions of the proposed procurement without a bid price; (b) all first stage bids, which are otherwise eligible, shall be evaluated through an appropriate committee constituted by the Ministry/Department; (c) the committee may hold discussions with the bidders and if any such discussions is held, equal opportunity shall be given to all bidders to participate in the discussions; (d) in revising the relevant terms and conditions of the procurement, the procuring entity shall not modify the fundamental nature of the procurement itself, but may add, amend or omit any specification of the subject matter of procurement or criterion for evaluation; (e) in the second stage … the procuring entity shall invite bids from all those bidders whose bids at the first stage were not rejected, to present final bid with bid prices in response to a revised set of terms and conditions; (f) any bidder, invited to bid but not in a position to supply the subject matter of procurement due to modification in the specifications or terms and conditions, may withdraw from the bidding proceedings without forfeiting any bid security … by declaring his intention to withdraw from the procurement proceedings with adequate justification.',
 hi:'Two-stage bidding tab jab specifications bidders ke inputs ke bina formulate na ho saken, technology tezi se badal rahi ho, R&D contract ho, ya detailed survey/risk assessment chahiye ho.',
 subs:[
  {n:'164(i)(a)', text:'Not feasible to formulate detailed specifications or identify specific characteristics without receiving inputs regarding technical aspects from bidders.', hi:'Specification bina bidder input ke nahi ban sakti.'},
  {n:'164(i)(b)', text:'The character of the subject matter of procurement is subject to rapid technological advances or market fluctuations or both.', hi:'Technology/market tezi se badalti ho.'},
  {n:'164(i)(c)', text:'Ministry/Department seeks to enter into a contract for the purpose of research, experiment, study or development, except where the contract includes production of items in quantities sufficient to establish commercial viability or to recover R&D costs.', hi:'R&D/experiment/study contract.'},
  {n:'164(i)(d)', text:'The bidder is expected to carry out a detailed survey or investigation and undertake a comprehensive assessment of risks, costs and obligations associated with the particular procurement.', hi:'Detailed survey/risk assessment chahiye.'},
  {n:'164(ii)(a)', text:'First stage: invite bids through advertised tender containing technical aspects and contractual terms and conditions of the proposed procurement without a bid price.', hi:'Stage 1 — bina price ke advertised tender.'},
  {n:'164(ii)(b)', text:'All first stage bids, which are otherwise eligible, shall be evaluated through an appropriate committee constituted by the Ministry/Department.', hi:'Stage 1 bids appropriate committee evaluate karegi.'},
  {n:'164(ii)(c)', text:'The committee may hold discussions with the bidders and if any such discussions is held, equal opportunity shall be given to all bidders to participate in the discussions.', hi:'Discussion ho to sabhi bidders ko barabar mauka.'},
  {n:'164(ii)(d)', text:'In revising the relevant terms and conditions, the procuring entity shall not modify the fundamental nature of the procurement itself, but may add, amend or omit any specification or criterion for evaluation.', hi:'Fundamental nature nahi badal sakta; specification/criterion badal sakti hai.'},
  {n:'164(ii)(e)', text:'Second stage: invite bids from all those bidders whose first-stage bids were not rejected, to present final bid with bid prices in response to a revised set of terms and conditions.', hi:'Stage 2 — non-rejected bidders ko revised terms ke saath final price bid.'},
  {n:'164(ii)(f)', text:'Any bidder invited to bid but not in a position to supply due to modification in specifications or terms and conditions may withdraw without forfeiting any bid security, by declaring his intention to withdraw with adequate justification.', hi:'Specification badalne par bina penalty ke withdraw kar sakte hain.'}
 ],
 fn:[]},

{r:'165', t:'Late Bids',
 text:'In the case of advertised tender enquiry or limited tender enquiry, late bids (i.e. bids received after the specified date and time for receipt of bids) should not be considered.',
 hi:'Advertised ya limited tender enquiry mein specified date/time ke baad aaye bids consider nahi hongi.',
 fn:[]},

{r:'166', t:'Single Tender Enquiry',
 text:'Procurement from a single source may be resorted to in the following circumstances: (i) It is in the knowledge of the user department that only a particular firm is the manufacturer of the required goods. (ii) In a case of emergency, the required goods are necessarily to be purchased from a particular source and the reason for such decision is to be recorded and approval of competent authority obtained. (iii) For standardization of machinery or spare parts to be compatible to the existing sets of equipment (on the advice of a competent technical expert and approved by the competent authority), the required item is to be purchased only from a selected firm.',
 hi:'Single source sirf teen haalaton mein. (i) aur (iii) mein Proprietary Article Certificate (PAC) chahiye. Emergency mein reason record + competent authority approval.',
 subs:[
  {n:'166(i)', text:'It is in the knowledge of the user department that only a particular firm is the manufacturer of the required goods.', hi:'Sirf ek hi firm manufacturer hai — PAC required.'},
  {n:'166(ii)', text:'In a case of emergency, the required goods are necessarily to be purchased from a particular source and the reason for such decision is to be recorded and approval of competent authority obtained.', hi:'Emergency — reason record + competent authority approval.'},
  {n:'166(iii)', text:'For standardization of machinery or spare parts to be compatible to the existing sets of equipment (on the advice of a competent technical expert and approved by the competent authority), the required item is to be purchased only from a selected firm.', hi:'Standardization — competent technical expert ki advice + competent authority approval — PAC required.'}
 ],
 note:['Proprietary Article Certificate (PAC) in the following form is to be provided by the Ministry/Department before procuring goods from a single source under sub-Rule 166(i) and 166(iii): (i) The indented goods are manufactured by M/s …; (ii) No other make or model is acceptable for the following reasons: …; (iii) Concurrence of finance wing to the proposal vide: …; (iv) Approval of the competent authority vide: … (Signature with date and designation of the indenting officer).'],
 ex:['PAC is required for sub-Rules 166(i) and 166(iii) only — not for 166(ii) (emergency).'],
 fn:[]},

{r:'167', t:'Electronic Reverse Auction',
 text:'Electronic Reverse Auction means an online real-time purchasing technique utilised by the procuring entity to select the successful bid, which involves presentation by bidders of successively more favourable bids during a scheduled period of time and automatic evaluation of bids. A procuring entity may choose to procure a subject matter of procurement by the electronic reverse auction method, if: (a) It is feasible for the procuring entity to formulate a detailed description of the subject matter of the procurement; (b) There is a competitive market of bidders anticipated to be qualified to participate in the electronic reverse auction, so that effective competition is ensured; (c) The criteria to be used by the procuring entity in determining the successful bid are quantifiable and can be expressed in monetary terms. The procedure for electronic reverse auction shall include the following: (a) The procuring entity shall solicit bids through an invitation to the electronic reverse auction to be published or communicated in accordance with the provisions similar to e-procurement; and (b) The invitation shall, in addition to the information as specified in e-procurement, include details relating to access to and registration for the auction, opening and closing of the auction and Norms for conduct of the auction.',
 hi:'E-reverse auction tab jab detailed description ban sakti ho, competitive market ho, aur successful bid ke criteria monetary terms mein quantify ho saken.',
 subs:[
  {n:'167(i) — Definition', text:'An online real-time purchasing technique utilised by the procuring entity to select the successful bid, which involves presentation by bidders of successively more favourable bids during a scheduled period of time and automatic evaluation of bids.', hi:'Online real-time technique — bidders successively better bids dete hain, automatic evaluation.'},
  {n:'167(ii)(a)', text:'It is feasible for the procuring entity to formulate a detailed description of the subject matter of the procurement.', hi:'Detailed description feasible ho.'},
  {n:'167(ii)(b)', text:'There is a competitive market of bidders anticipated to be qualified to participate in the electronic reverse auction, so that effective competition is ensured.', hi:'Competitive market ho taaki effective competition ensure ho.'},
  {n:'167(ii)(c)', text:'The criteria to be used by the procuring entity in determining the successful bid are quantifiable and can be expressed in monetary terms.', hi:'Criteria monetary terms mein quantify ho saken.'},
  {n:'167(iii)(a)', text:'The procuring entity shall solicit bids through an invitation to the electronic reverse auction to be published or communicated in accordance with the provisions similar to e-procurement.', hi:'Invitation e-procurement jaise publish/communicate karo.'},
  {n:'167(iii)(b)', text:'The invitation shall, in addition to the information as specified in e-procurement, include details relating to access to and registration for the auction, opening and closing of the auction and Norms for conduct of the auction.', hi:'Invitation mein access, registration, opening/closing, aur conduct norms bhi hon.'}
 ],
 fn:[]},

{r:'168', t:'Contents of Bidding Document',
 text:'All the terms, conditions, stipulations and information to be incorporated in the bidding document are to be shown in the appropriate chapters as below: Chapter-1: Instructions to Bidders. Chapter-2: Conditions of Contract. Chapter-3: Schedule of Requirements. Chapter-4: Specifications and allied Technical Details. Chapter-5: Price Schedule (to be utilised by the bidders for quoting their prices). Chapter-6: Contract Form. Chapter-7: Other Standard Forms, if any, to be utilised by the purchaser and the bidders.',
 hi:'Bidding document ke 7 standard chapters — inhi order mein.',
 subs:[
  {n:'Chapter-1', text:'Instructions to Bidders.', hi:'Bidders ko instructions.'},
  {n:'Chapter-2', text:'Conditions of Contract.', hi:'Contract ki conditions.'},
  {n:'Chapter-3', text:'Schedule of Requirements.', hi:'Requirement schedule.'},
  {n:'Chapter-4', text:'Specifications and allied Technical Details.', hi:'Specifications aur technical details.'},
  {n:'Chapter-5', text:'Price Schedule (to be utilised by the bidders for quoting their prices).', hi:'Price schedule — bidders yahan quote karenge.'},
  {n:'Chapter-6', text:'Contract Form.', hi:'Contract form.'},
  {n:'Chapter-7', text:'Other Standard Forms, if any, to be utilised by the purchaser and the bidders.', hi:'Doosre standard forms.'}
 ],
 fn:[]},

{r:'169', t:'Maintenance Contract',
 text:'Depending on the cost and nature of the goods to be purchased, it may also be necessary to enter into maintenance contract(s) of suitable period either with the supplier of the goods or with any other competent firm, not necessarily the supplier of the subject goods. Such maintenance contracts are especially needed for sophisticated and costly equipment and machinery. It may, however, be kept in mind that the equipment or machinery is maintained free of charge by the supplier during its warranty period or such other extended periods as the contract terms may provide and the paid maintenance should commence only thereafter.',
 hi:'Sophisticated/costly equipment ke liye maintenance contract — supplier se ya kisi doosre competent firm se. Warranty ke dauraan maintenance free of charge; paid maintenance uske baad.',
 note:['Warranty period (and any extended period as per contract terms) — maintenance is free of charge by the supplier; paid maintenance commences only thereafter.'],
 fn:[]},

{r:'170', t:'Bid Security',
 text:'To safeguard against a bidder\u2019s withdrawing or altering its bid during the bid validity period in the case of advertised or limited tender enquiry, Bid Security (also known as Earnest Money) is to be obtained from the bidders except Micro and Small Enterprises (MSEs) as defined in MSE Procurement Policy issued by Department of Micro, Small and Medium Enterprises (MSME) or are registered with the Central Purchase Organisation or the concerned Ministry or Department or Startups as recognized by Department for Promotion of Industry and Internal Trade (DPIIT). The bidders should be asked to furnish bid security along with their bids. Amount of bid security should ordinarily range between two percent to five percent of the estimated value of the goods to be procured. The amount of bid security should be determined accordingly by the Ministry or Department and indicated in the bidding documents. The bid security may be accepted in the form of Insurance Surety Bonds, Account Payee Demand Draft, Fixed Deposit Receipt, Banker\u2019s Cheque or Bank Guarantee including e-Bank Guarantee from any of the Commercial Banks or payment online in an acceptable form, safeguarding the purchaser\u2019s interest in all respects. The bid security is normally to remain valid for a period of forty-five days beyond the final bid validity period. Bid securities of the unsuccessful bidders should be returned to them at the earliest after expiry of the final bid validity and latest on or before the 30th day after the award of the contract. However, in case of two packet or two stage bidding, Bid securities of unsuccessful bidders during first stage i.e. technical evaluation etc. should be returned within 30 days of declaration of result of first stage i.e. technical evaluation etc. In place of a Bid security, the Ministries/Departments may require Bidders to sign a Bid securing declaration accepting that if they withdraw or modify their Bids during the period of validity, or if they are awarded the contract and they fail to sign the contract, or to submit a performance security before the deadline defined in the request for bids document, they will be suspended for the period of time specified in the request for bids document from being eligible to submit Bids for contracts with the entity that invited the Bids.',
 hi:'EMD 2–5% of estimated value. MSEs aur DPIIT-recognised Startups exempt. Valid 45 days beyond final bid validity. Unsuccessful bidders ko latest 30th day after award tak wapas. Forms: Insurance Surety Bond, APDD, FDR, Banker\u2019s Cheque, BG/e-BG, online payment.',
 subs:[
  {n:'170(i) — exemption', text:'Bid Security is to be obtained from the bidders except Micro and Small Enterprises (MSEs) as defined in MSE Procurement Policy issued by MSME or are registered with the Central Purchase Organisation or the concerned Ministry or Department or Startups as recognized by DPIIT.', hi:'MSEs aur DPIIT Startups — EMD se exempt.'},
  {n:'170(i) — amount', text:'Amount of bid security should ordinarily range between two percent to five percent of the estimated value of the goods to be procured … determined by the Ministry or Department and indicated in the bidding documents.', hi:'2%–5% estimated value; bidding document mein mention ho.'},
  {n:'170(i) — forms', text:'Insurance Surety Bonds, Account Payee Demand Draft, Fixed Deposit Receipt, Banker\u2019s Cheque or Bank Guarantee including e-Bank Guarantee from any of the Commercial Banks or payment online in an acceptable form.', hi:'5 acceptable forms + online payment.'},
  {n:'170(i) — validity', text:'The bid security is normally to remain valid for a period of forty-five days beyond the final bid validity period.', hi:'45 din beyond final bid validity.'},
  {n:'170(ii) — refund', text:'Bid securities of the unsuccessful bidders should be returned to them at the earliest after expiry of the final bid validity and latest on or before the 30th day after the award of the contract. However, in case of two packet or two stage bidding, Bid securities of unsuccessful bidders during first stage i.e. technical evaluation etc. should be returned within 30 days of declaration of result of first stage.', hi:'Unsuccessful bidders — latest 30th day after award; two-packet/two-stage — 30 din mein first-stage result ke.'},
  {n:'170(iii) — alternative', text:'In place of a Bid security, the Ministries/Departments may require Bidders to sign a Bid securing declaration … they will be suspended for the period of time specified in the request for bids document from being eligible to submit Bids for contracts with the entity that invited the Bids.', hi:'EMD ki jagah Bid Securing Declaration bhi le sakte hain — violation par suspension.'}
 ],
 ex:['MSEs (as defined in the MSME MSE Procurement Policy) and those registered with the Central Purchase Organisation or the concerned Ministry/Department; and DPIIT-recognised Startups — exempt from bid security.'],
 fn:['Startups exemption inserted vide DoE OM No. F.20/2/2014-PPD(Pt.) dated 25.07.2017.',
     'Insurance Surety Bonds inserted vide DoE OM No. F.1/1/2022-PPD dated 02.02.2022.',
     'e-Bank Guarantee inserted vide DoE OM No. F.1/4/2022-PPD dated 05.08.2022.',
     'Two-packet/two-stage refund proviso inserted vide DoE OM No. F.1/2/2022-PPD dated 01.04.2022.']},

{r:'171', t:'Performance Security',
 text:'To ensure due performance of the contract, Performance Security is to be obtained from the successful bidder awarded the contract. Unlike contracts of Works and Plants, in case of contracts for goods, the need for the Performance Security depends on the market conditions and commercial practice for the particular kind of goods. Performance Security, in respect of procurement only of Goods/Consultancy Services/Non Consultancy Services, should be for an amount of three to five per cent (3-5%) of the value of the contract as specified in the bid documents. Performance Security may be furnished in the form of Insurance Surety Bond, Account Payee Demand Draft, Fixed Deposit Receipt from a Commercial bank, Bank Guarantee including e-Bank Guarantee from a Commercial bank or online payment in an acceptable form safeguarding the purchaser\u2019s interest in all respects. Performance Security should remain valid for a period of sixty days beyond the date of completion of all contractual obligations of the supplier including warranty obligations. Bid security should be refunded to the successful bidder on receipt of Performance Security.',
 hi:'Performance security 3–5% of contract value (goods / consultancy / non-consultancy services). Valid 60 days beyond completion of ALL contractual obligations including warranty. EMD successful bidder ko PS milne par wapas.',
 subs:[
  {n:'171(i)', text:'Performance Security is to be obtained from the successful bidder awarded the contract … for an amount of three to five per cent (3-5%) of the value of the contract as specified in the bid documents. Forms: Insurance Surety Bond, Account Payee Demand Draft, Fixed Deposit Receipt, Bank Guarantee including e-Bank Guarantee, or online payment.', hi:'3–5% contract value; forms wahi jaise EMD.'},
  {n:'171(ii)', text:'Performance Security should remain valid for a period of sixty days beyond the date of completion of all contractual obligations of the supplier including warranty obligations.', hi:'60 din beyond saari obligations + warranty.'},
  {n:'171(iii)', text:'Bid security should be refunded to the successful bidder on receipt of Performance Security.', hi:'EMD refund = PS milne par.'}
 ],
 note:['Amount of performance security plus security deposit/retention money for procurement of WORKS will continue to be 3% to 10%.'],
 ex:['For goods contracts, the need for performance security depends on market conditions and commercial practice for the particular kind of goods.','Works: performance security + security deposit/retention money continues at 3% to 10%.'],
 fn:['Amended vide DoE OM No. F.1/2/2023-PPD dated 01.01.2024 (3-5% for Goods/Consultancy/Non-Consultancy Services).',
     'Insurance Surety Bond inserted vide DoE OM No. F.1/1/2022-PPD dated 02.02.2022.',
     'e-Bank Guarantee inserted vide DoE OM No. F.1/4/2022-PPD dated 05.08.2022.']},

{r:'172(1)', t:'Advance payment to supplier',
 text:'Ordinarily, payments for services rendered or supplies made should be released only after the services have been rendered or supplies made. However, it may become necessary to make advance payments for example in the following types of cases: (i) Advance payment demanded by firms holding maintenance contracts for servicing of Air-conditioners, computers, other costly equipment, etc. (ii) Advance payment demanded by firms against fabrication contracts, turn-key contracts etc. Such advance payments should not exceed the following limits: (a) Thirty per cent of the contract value to private firms; (b) Forty per cent of the contract value to a State or Central Government agency or a Public Sector Undertaking; or (c) in case of maintenance contract, the amount should not exceed the amount payable for six months under the contract. Ministries or Departments of the Central Government may relax, in consultation with their Financial Advisers concerned, the ceilings (including percentage laid down for advance payment for private firms) mentioned above. While making any advance payment as above, adequate safeguards in the form of bank guarantee etc. should be obtained from the firm.',
 hi:'Ordinarily payment ke baad hi. Advance do situations mein: maintenance contracts (AC, computers, costly equipment) aur fabrication/turn-key contracts. Ceilings: 30% private firms, 40% Govt agency/PSU, maintenance contract ≤ 6 months value. Bank guarantee safeguards.',
 subs:[
  {n:'172(1)(i)', text:'Advance payment demanded by firms holding maintenance contracts for servicing of Air-conditioners, computers, other costly equipment, etc.', hi:'Maintenance contract firms.'},
  {n:'172(1)(ii)', text:'Advance payment demanded by firms against fabrication contracts, turn-key contracts etc.', hi:'Fabrication / turn-key contracts.'},
  {n:'172(1)(a)', text:'Thirty per cent of the contract value to private firms.', hi:'Private firms — max 30%.'},
  {n:'172(1)(b)', text:'Forty per cent of the contract value to a State or Central Government agency or a Public Sector Undertaking.', hi:'Govt agency / PSU — max 40%.'},
  {n:'172(1)(c)', text:'In case of maintenance contract, the amount should not exceed the amount payable for six months under the contract.', hi:'Maintenance contract — 6 mahine ke amount tak.'},
  {n:'172(1) — relaxation', text:'Ministries or Departments may relax, in consultation with their Financial Advisers concerned, the ceilings (including percentage for private firms). While making any advance payment, adequate safeguards in the form of bank guarantee etc. should be obtained.', hi:'FA se consult kar ke ceilings relax ho sakti hain; bank guarantee safeguard.'}
 ],
 fn:[]},

{r:'172(2)', t:'Part payment to suppliers',
 text:'Depending on the terms of delivery incorporated in a contract, part payment to the supplier may be released after it dispatches the goods from its premises in terms of the contract.',
 hi:'Delivery terms ke hisaab se, supplier ke premises se goods dispatch hone par part payment release ho sakti hai.',
 fn:[]},

{r:'173', t:'Transparency, competition, fairness and elimination of arbitrariness in the procurement process',
 text:'All government purchases should be made in a transparent, competitive and fair manner, to secure best value for money. This will also enable the prospective bidders to formulate and send their competitive bids with confidence. Some of the measures for ensuring the above are as follows:',
 hi:'Sabse lamba rule — 22 sub-points. Yahan se hi Code of Integrity (Rule 175) nikla hai. NIL charges = unresponsive bid, negotiation discouraged, single bid bhi valid ho sakta hai — ye sab yahin hai.',
 subs:[
  {n:'173(i)(a)–(i)', text:'The text of the bidding document should be self-contained and comprehensive without any ambiguities … The condition of prior turnover and prior experience may be relaxed for Startups … The bidding document should contain: (a) Description and Specifications of goods including nature, quantity, time and place(s) of delivery; (b) criteria for eligibility and qualifications …; (c) eligibility criteria for goods indicating legal restrictions about the origin of goods; (d) procedure, date, time and place for sending the bids; (e) date, time and place of opening of the bid; (f) criteria for evaluation of bids; (g) special terms affecting performance; (h) essential terms of the procurement contract; (i) a clause that "if a firm quotes NIL charges/consideration, the bid shall be treated as unresponsive and will not be considered".', hi:'Bidding document self-contained; Startups ke liye turnover/experience relax; 9 contents; NIL charge = unresponsive.'},
  {n:'173(iii)', text:'Modification to bidding document: (a) any modification/clarification materially affecting terms shall be published or communicated in the same manner as the initial bidding document; (b) if more time is required, the time limit shall be extended before the last date for submission of bids; (c) any bidder who has submitted a bid shall have the opportunity to modify or resubmit it, or withdraw it in case the modification materially affects the essential terms, within the period initially allotted or extended; provided the bid last submitted or as modified shall be considered for evaluation.', hi:'Modification same manner mein communicate; time extend; bidder ko modify/resubmit/withdraw ka mauka.'},
  {n:'173(iv)', text:'Suitable provision should be kept in the bidding document to enable a bidder to question the bidding conditions, bidding process and/or rejection of its bid. The reasons for rejecting a tender or non-issuing a tender document to a prospective bidder must be disclosed where enquiries are made by the bidder.', hi:'Rejection ke reasons disclose karne honge.'},
  {n:'173(v)–(vii)', text:'Suitable provision for settlement of disputes; the bidding document should indicate clearly that the resultant contract will be interpreted under Indian Laws; bidders should be given reasonable time to prepare and send their bids.', hi:'Dispute settlement; Indian Laws; reasonable time.'},
  {n:'173(viii)', text:'The bids should be opened in public and authorised representatives of the bidders should be permitted to attend the bid opening.', hi:'Bid opening public — bidders ke authorised representatives attend kar sakte hain.'},
  {n:'173(x)', text:'Pre-bid conference: in case of turn-key contract(s) or contract(s) of special nature for procurement of sophisticated and costly equipment or wherever felt necessary, a suitable provision is to be kept for one or more rounds of pre-bid conference … The records of such conference shall be intimated to all bidders and shall also be exhibited on the website(s) where tender was published.', hi:'Sophisticated/costly equipment mein pre-bid conference; records sabhi bidders tak + website par.'},
  {n:'173(xi)', text:'Criteria for determining responsiveness: (a) time of delivery; (b) performance/efficiency/environmental characteristics; (c) terms of payment and of guarantees; (d) price; (e) cost of operating, maintaining and repairing etc.', hi:'Responsiveness ke 5 criteria.'},
  {n:'173(xii)', text:'Bids received should be evaluated in terms of the conditions already incorporated in the bidding documents; no new condition should be brought in for evaluation. Determination of a bid\u2019s responsiveness should be based on the contents of the bid itself without recourse to extrinsic evidence.', hi:'Naya condition evaluation mein nahi; bid ke contents par hi decide.'},
  {n:'173(xiii)', text:'Bidders should not be permitted to alter or modify their bids after expiry of the deadline for receipt of bids.', hi:'Deadline ke baad koi modification nahi.'},
  {n:'173(xiv)', text:'Negotiation with bidders after bid opening must be severely discouraged. However, in exceptional circumstances where price negotiation against an ad-hoc procurement is necessary due to some unavoidable circumstances, the same may be resorted to only with the lowest evaluated responsive bidder.', hi:'Negotiation discouraged; sirf L-1 ke saath exceptional circumstances mein.'},
  {n:'173(xvi)', text:'Contract should ordinarily be awarded to the lowest evaluated bidder whose bid has been found to be responsive and who is eligible and qualified … where the lowest acceptable bidder is not in a position to supply the full quantity, the remaining quantity, as far as possible, be ordered from the next higher responsive bidder at the rates offered by the lowest responsive bidder.', hi:'Ordinarily L-1 ko award; partial supply par baaki quantity next higher bidder se L-1 rates par.'},
  {n:'173(xvii)', text:'Procurement of Energy Efficient Electrical Appliances: Ministries/Departments while procuring electrical appliances notified by DoE shall ensure that they carry the notified threshold or higher Star Rating of Bureau of Energy Efficiency (BEE).', hi:'BEE Star Rating wale appliances.'},
  {n:'173(xviii)', text:'The name of the successful bidder awarded the contract should be mentioned in the CPPP, Ministries or Departments website and their notice board or bulletin.', hi:'Successful bidder ka naam CPPP + website + notice board par.'},
  {n:'173(xix)', text:'Rejection of all Bids is justified when: (a) effective competition is lacking; (b) all Bids and Proposals are not substantially responsive to the requirements of the Procurement Documents; (c) the Bids\u2019/Proposals\u2019 prices are substantially higher than the updated cost estimate or available budget; or (d) none of the technical Proposals meets the minimum technical qualifying score.', hi:'Sab bids reject karne ke 4 grounds.'},
  {n:'173(xx)', text:'Lack of competition shall not be determined solely on the basis of the number of Bidders. Even when only one Bid is submitted, the process may be considered valid provided: (a) the procurement was satisfactorily advertised and sufficient time was given; (b) the qualification criteria were not unduly restrictive; and (c) prices are reasonable in comparison to market values.', hi:'Ek hi bid aaye to bhi process valid ho sakta hai — 3 conditions.'},
  {n:'173(xxi)', text:'When a limited or open tender results in only one effective offer, it shall be treated as a single tender contract.', hi:'Ek hi effective offer = single tender contract.'},
  {n:'173(xxii)', text:'In case a purchase Committee is constituted to purchase or recommend the procurement, no member of the purchase Committee should be reporting directly to any other member of such Committee in case estimated value of procurement exceeds ₹50 lakhs.', hi:'₹50 lakh se upar — committee member doosre member ko directly report na kare.'}
 ],
 ex:['Startups — prior turnover and prior experience conditions may be relaxed, subject to meeting quality & technical specifications.','Sub-rule (xv) has been deleted.'],
 fn:['Sub-rule (xv) deleted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.',
     'Rule 173(xxii) threshold amended vide DoE OM No. F.1/3/2024-PPD dated 10.07.2024.']},

{r:'174', t:'Efficiency, Economy and Accountability in Public Procurement System',
 text:'Public procurement procedure should ensure efficiency, economy and accountability in the system. To achieve the same, the following keys areas should be addressed: (i) To reduce delay, appropriate time frame for each stage of procurement should be prescribed by the Ministry or Department. (ii) To minimise the time needed for decision making and placement of contract, every Ministry/Department, with the approval of the competent authority, may delegate, wherever necessary, appropriate purchasing powers to the lower functionaries. (iii) The Ministries or Departments should ensure placement of contract within the original validity of the bids. Extension of bid validity must be discouraged and resorted to only in exceptional circumstances.',
 hi:'Har stage ka time frame prescribe karo; zaroorat pade to purchasing powers lower functionaries ko delegate karo; contract original bid validity ke andar place karo — extension discourage.',
 subs:[
  {n:'174(i)', text:'To reduce delay, appropriate time frame for each stage of procurement should be prescribed by the Ministry or Department.', hi:'Har stage ka time frame.'},
  {n:'174(ii)', text:'To minimise the time needed for decision making and placement of contract, every Ministry/Department, with the approval of the competent authority, may delegate, wherever necessary, appropriate purchasing powers to the lower functionaries.', hi:'Lower functionaries ko purchasing powers delegate.'},
  {n:'174(iii)', text:'The Ministries or Departments should ensure placement of contract within the original validity of the bids. Extension of bid validity must be discouraged and resorted to only in exceptional circumstances.', hi:'Contract original validity ke andar; extension discourage.'},
  {n:'174(iv)', text:'[Deleted]', hi:'Sub-rule (iv) delete ho chuka hai.'}
 ],
 fn:['Sub-rule (iv) deleted vide DoE OM No. F.1/26/2018-PPD dated 02.04.2019.']},

{r:'175(1)', t:'Code of Integrity',
 text:'No official of a procuring entity or a bidder shall act in contravention of the codes which includes (i) prohibition of (a) making offer, solicitation or acceptance of bribe, reward or gift or any material benefit, either directly or indirectly, in exchange for an unfair advantage in the procurement process or to otherwise influence the procurement process; (b) any omission, or misrepresentation that may mislead or attempt to mislead so that financial or other benefit may be obtained or an obligation avoided; (c) any collusion, bid rigging or anticompetitive behavior that may impair the transparency, fairness and the progress of the procurement process; (d) improper use of information provided by the procuring entity to the bidder with an intent to gain unfair advantage in the procurement process or for personal gain; (e) any financial or business transactions between the bidder and any official of the procuring entity related to tender or execution process of contract, which can affect the decision of the procuring entity directly or indirectly; (f) any coercion or any threat to impair or harm, directly or indirectly, any party or its property to influence the procurement process; (g) obstruction of any investigation or auditing of a procurement process; (h) making false declaration or providing false information for participation in a tender process or to secure a contract; (ii) disclosure of conflict of interest; (iii) Disclosure by the bidder of any previous transgressions made in respect of the provisions of sub-clause (i) with any entity in any country during the last three years or of being debarred by any other procuring entity.',
 hi:'Code of Integrity — officers aur bidders dono par lagu. 8 prohibitions (bribe, misrepresentation, collusion/bid rigging, improper use of information, financial transactions with officials, coercion, obstruction, false declaration) + conflict of interest disclosure + pichhle 3 saal ke transgressions ki disclosure.',
 subs:[
  {n:'175(1)(i)(a)', text:'Making offer, solicitation or acceptance of bribe, reward or gift or any material benefit, directly or indirectly, in exchange for an unfair advantage in the procurement process or to otherwise influence it.', hi:'Rishwat, reward, gift — mana hai.'},
  {n:'175(1)(i)(b)', text:'Any omission, or misrepresentation that may mislead or attempt to mislead so that financial or other benefit may be obtained or an obligation avoided.', hi:'Chhipana ya galat presentation — mana hai.'},
  {n:'175(1)(i)(c)', text:'Any collusion, bid rigging or anticompetitive behavior that may impair the transparency, fairness and the progress of the procurement process.', hi:'Collusion / bid rigging / anticompetitive behaviour.'},
  {n:'175(1)(i)(d)', text:'Improper use of information provided by the procuring entity to the bidder with an intent to gain unfair advantage in the procurement process or for personal gain.', hi:'Di gayi information ka galat use.'},
  {n:'175(1)(i)(e)', text:'Any financial or business transactions between the bidder and any official of the procuring entity related to tender or execution process of contract, which can affect the decision directly or indirectly.', hi:'Bidder aur official ke beech financial/business transactions.'},
  {n:'175(1)(i)(f)', text:'Any coercion or any threat to impair or harm, directly or indirectly, any party or its property to influence the procurement process.', hi:'Dhamki ya nuksaan.'},
  {n:'175(1)(i)(g)', text:'Obstruction of any investigation or auditing of a procurement process.', hi:'Investigation/audit mein rukawat.'},
  {n:'175(1)(i)(h)', text:'Making false declaration or providing false information for participation in a tender process or to secure a contract.', hi:'Jhooti declaration / jhooti information.'},
  {n:'175(1)(ii)', text:'Disclosure of conflict of interest.', hi:'Conflict of interest disclose karna zaroori.'},
  {n:'175(1)(iii)', text:'Disclosure by the bidder of any previous transgressions made in respect of the provisions of sub-clause (i) with any entity in any country during the last three years or of being debarred by any other procuring entity.', hi:'Pichhle 3 saal ke transgressions / debarment ki disclosure.'}
 ],
 fn:[]},

{r:'175(2)', t:'Action on breach of the Code of Integrity',
 text:'The procuring entity, after giving a reasonable opportunity of being heard, comes to the conclusion that a bidder or prospective bidder, as the case may be, has contravened the code of integrity, may take appropriate measures.',
 hi:'Code of integrity todne par bhi pehle reasonable opportunity of being heard deni hogi, phir appropriate measures.',
 fn:[]},

{r:'176', t:'Buy-Back Offer',
 text:'When it is decided with the approval of the competent authority to replace an existing old item(s) with a new and better version, the department may trade the existing old item while purchasing the new one. For this purpose, a suitable clause is to be incorporated in the bidding document so that the prospective and interested bidders formulate their bids accordingly. Depending on the value and condition of the old item to be traded, the time as well as the mode of handing over the old item to the successful bidder should be decided and relevant details in this regard suitably incorporated in the bidding document. Further, suitable provision should also be kept in the bidding document to enable the purchaser either to trade or not to trade the item while purchasing the new one.',
 hi:'Purana item naye se replace karna ho to use trade kar sakte hain — competent authority ki approval se, bidding document mein suitable clause ke saath. Handing over ka time aur mode bidding document mein.',
 subs:[
  {n:'176 — condition', text:'Decided with the approval of the competent authority to replace an existing old item(s) with a new and better version.', hi:'Competent authority ki approval zaroori.'},
  {n:'176 — clause', text:'A suitable clause is to be incorporated in the bidding document so that the prospective and interested bidders formulate their bids accordingly.', hi:'Bidding document mein trade clause.'},
  {n:'176 — handover', text:'Depending on the value and condition of the old item, the time as well as the mode of handing over the old item to the successful bidder should be decided and relevant details incorporated in the bidding document.', hi:'Handover ka time aur mode decide karo.'},
  {n:'176 — option', text:'Suitable provision should be kept in the bidding document to enable the purchaser either to trade or not to trade the item while purchasing the new one.', hi:'Trade kare ya na kare — purchaser ke paas option rahe.'}
 ],
 fn:[]}
];
